  Q.x19 = ['¿Qué calcula este código?', ['Un total de ingresos por ciudad', 'Los ingresos de cada fila', 'El número de ciudades', 'La media de ingresos por fila'], 'groupby separa las filas por ciudad y después sum() reduce cada grupo a un número.'];
